import { describe, expect, it } from 'vitest';
import { isMuted, toggleMute, type MuteSettings } from '../muteSettings';

describe('muteSettings', () => {
  it('mutes an unmuted chat', () => {
    const next = toggleMute({ mutedChatIds: ['a'] }, 'b');
    expect(next.mutedChatIds).toEqual(['a', 'b']);
  });

  it('does not mutate the input settings', () => {
    const input: MuteSettings = { mutedChatIds: ['a'] };
    const next = toggleMute(input, 'b');
    expect(input.mutedChatIds).toEqual(['a']);
    expect(next).not.toBe(input);
  });

  it('unmutes a muted chat and keeps the order of the others', () => {
    const next = toggleMute({ mutedChatIds: ['a', 'b', 'c'] }, 'b');
    expect(next.mutedChatIds).toEqual(['a', 'c']);
  });

  it('isMuted reports membership', () => {
    const settings: MuteSettings = { mutedChatIds: ['a'] };
    expect(isMuted(settings, 'a')).toBe(true);
    expect(isMuted(settings, 'b')).toBe(false);
  });
});
